-- Isles of Giants, the Blood Tide look.
--   * every Zandalari on the island is the real Mists of Pandaria model. Most of them were gnomes, humans, undead or a
--     murloc until now, because their display ids had been picked without reading what they are.
--   * the defenders are a mixed expedition that cannot be mistaken for them.
--   * direhorns are direhorns, and every beast is sized against a soldier. The red T-Rex was scale 3 before the template
--     scale, and the Behemoth at 8 would have been over 100 yards long.
--   * weapon sets for all of them, and spawn rows that had a weapon row but equipment_id 0 now carry it.
-- Needs CreatureDisplayInfo.dbc and CreatureModelData.dbc with display rows 47245-48xxx and 507156-507160 on the server,
-- or these creatures refuse to load.

DELETE FROM `creature_model_info` WHERE `DisplayID` IN (47245, 47266, 47267, 47269, 47328, 47356, 47357, 47358, 47359, 47363, 47365, 47370, 47371, 47372, 47394, 47395, 47396, 47397, 47398, 47400, 47401, 47402, 47412, 47413, 47419, 47420, 47421, 47422, 47427, 47429, 47430, 47431, 47432, 47436, 47440, 47584, 47585, 47586, 47587, 47590, 47591, 47622, 47623, 47624, 47625, 47668, 47673, 47678, 47679, 47680, 47681, 47682, 47683, 47684, 47763, 47764, 47830, 47831, 47832, 47833, 47868, 47885, 47900, 507156, 507157, 507158, 507159, 507160);

DELETE FROM `creature_template_model` WHERE `CreatureID` IN (400270, 400271, 400272, 400275, 400276, 400326, 400327, 400328, 400329, 400330, 400331, 400332, 400333, 400334, 400336, 400337, 400338, 400580, 400581, 400583, 400586, 400588, 400590, 400594, 401004, 401005, 401006, 401007, 401008, 401009, 400050, 400335, 400361, 400363, 400585, 400587, 400596);

DELETE FROM `creature_equip_template` WHERE `CreatureID` IN (400270, 400271, 400272, 400275, 400276, 400326, 400327, 400328, 400329, 400330, 400331, 400332, 400333, 400334, 400336, 400337, 400338, 400580, 400581, 400583, 400586, 400588, 400594, 401004, 401005, 401006, 401007, 401008, 401009);

UPDATE `creature` SET `equipment_id` = 1 WHERE `id` IN (400270, 400271, 400272, 400275, 400276, 400320, 400338, 401011, 401012) AND `guid` IN (9000133, 9000205, 9000416, 9000418, 9000424, 9000425, 9000426, 9000427, 9000428, 9000429, 9000430, 9010333, 9010334, 9010335);
